// 1. Inline — fine once, painful twice
const lesson: { title: string; minutes: number } = { title: "Interfaces", minutes: 20 };

// 2. Interface — a named, reusable contract
interface Lesson {
  title: string;
  minutes: number;
}

// 3. Type alias — a named, reusable… also a contract
type LessonT = {
  title: string;
  minutes: number;
}

// All three accept the same values and reject the same mistakes
const a: Lesson = { title: "Interfaces", minutes: 20 };  // ✓
const b: Lesson = { title: "Interfaces", minutes: "20" }; // Error: string ≠ number
const c: Lesson = { title: "Interfaces" };               // Error: minutes is missing

interface User {
  readonly id: number;    // cannot be reassigned after creation
  email: string;          // required
  role?: "admin" | "user"; // optional — may be absent/undefined
  nickname?: string;
}

const u: User = { id: 1, email: "ada@example.com" };  // ✓ role/nickname absent is fine
u.id = 2;                 // Error: cannot assign to 'id' — it's readonly

// But watch the fresh-literal rule:
const bad = { id: 1, email: "x@y.co", nickname: 42 };
const ok: User = bad;           // Error? No — structural pass… nickname: number fails!
// Error: Type 'number' is not assignable to 'string | undefined'.
const extra: User = { id: 1, email: "e", admin: true }; // Error: 'admin' does not exist

interface Content {
  title: string;
  minutes: number;
}

interface Lesson extends Content {
  quizCount: number;
}

interface Course extends Content {
  lessons: Lesson[];
}

// type-alias equivalent — intersection
type LessonT = Content & { quizCount: number };

// API envelope pattern, composed:
interface ApiResponse<T> {
  status: number;
  data: T;
  error?: string;
}

interface Scores {
  [student: string]: number;  // any string key → number value
}

const exam: Scores = { ada: 98, grace: 95 };  // ✓
exam.linus = "100";                          // Error: string ≠ number

// A stricter dictionary you'll meet in Lesson 7:
type Roles = Record<"admin" | "editor" | "viewer", string[]>;

// analytics.d.ts in your project — merges with the global Window interface
declare global {
  interface Window {
    __DEVPATH_CONFIG__?: { debug: boolean };
  }
}

// elsewhere in your app, now fully typed:
window.__DEVPATH_CONFIG__?.debug;  // boolean | undefined — no cast needed

interface User {
  readonly id: number;
  email: string;
  role?: "admin" | "user";
}

interface UsersResponse {
  status: number;
  data: User[];
  error?: string;
}

async function fetchUsers(url: string): Promise<UsersResponse> {
  const res = await fetch(url);
  // The body is unknown at this boundary — Lesson 8 validates before returning.
  return JSON.parse(await res.text()) as UsersResponse; // placeholder cast; fixed soon
}

