interface User {
  readonly id: number;
  email: string;
  displayName?: string;
}

interface Comment {
  readonly id: number;
  body: string;
  author: User;
  editedAt?: string;
  replies?: Comment[];   // self-reference models nesting
}

function countAllComments(comments: Comment[]): number {
  return comments.reduce(
    (sum, c) => sum + 1 + (c.replies ? countAllComments(c.replies) : 0),
    0
  );
}
